  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.tower28beauty.com/pages/athlete-ambassador', 'official_site', 'affiliate', 'Tower 28''s official Athlete (''Sweat'') Ambassador page states ''Earn on every order you drive — no cap'' for commission, with tiers unlocking gifting, store credit and commission; ambassadors get a referral link and a 10% follower discount code. The page''s commission percentage itself is not published, and the program targets student athletes. The no-cap quote comes from the search capture of the official page (the page''s JS section truncated in direct fetch), so it is marked publicly reported rather than verified.', 'publicly_reported', now());
