  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 25, 15, 8, 12, 5, 4, '{"niche_fit": "Clean makeup and skincare for sensitive skin \u2014 a core beauty UGC niche.", "ugc_evidence": "A tiered ambassador program on Superfiliate with co-branded landing pages, monthly payouts and top-ambassador prizes.", "compensation": "Commission is explicitly uncapped (''no cap'' on the official program page), but no percentage is published anywhere fetched, so this stays low per the rubric.", "contact_access": "A published partnerships email on the official contact page plus a live ambassador portal \u2014 near top band.", "opportunity_availability": "Applications are open but the program is aimed at student athletes, narrowing who can join.", "credibility": "Established LA clean-beauty brand with Sephora distribution."}'::jsonb);
