  insert into public.brands (name, website, description, country, status) values ('Nomatic', 'https://www.nomatic.com', 'Nomatic designs sleek, durable gear for modern travelers, creators, and commuters, including travel bags, camera gear, backpacks, wallets, and the Outset Collection. Its Awin affiliate program explicitly targets travel, lifestyle, EDC and tech influencers, YouTubers and bloggers doing gear reviews, and Instagram and TikTok creators showcasing travel and everyday carry.', 'United States', 'published') returning id into bid;
