  insert into public.brands (name, website, description, country, status) values ('Discover Cars', 'https://www.discovercars.com', 'DiscoverCars.com is a car rental comparison and booking platform headquartered in Riga, Latvia, working with more than 1,000 rental suppliers. Its affiliate program pays partners a share of its own profit on completed rentals, with an average commission of about $20 per booking and a 365-day cookie.', 'Latvia', 'published') returning id into bid;
