  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Discover Cars Car Rental Affiliate Program', 'https://www.discovercars.com/affiliate', 'https://www.discovercars.com/affiliate', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.discovercars.com/affiliate', 'official_site', 'affiliate_program_page', 'Official affiliate page fetched in full: ''You earn a 70% commission from our car rental profit and a 30% commission on Full Coverage... Your commission is a percentage of our profit, not of the price the customer pays.'' Page also states ~$20 average commission per booking, 365-day cookie lifetime, dedicated account manager, free sign-up in a few minutes, monthly payment via PayPal or wire transfer, and testimonial quotes from travel bloggers/content creators. NOTE: 70% is a share of Discover Cars'' profit, not of booking value.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.discovercars.com/affiliate-conditions', 'official_site', 'affiliate_terms', 'Official Affiliate Program Terms: 70% commission on car rentals and 30% on Full Coverage, percentages taken from Discover Cars'' profit, on completed bookings net of cancellations; cookie lifetime 365 days; payout invoiced once the amount exceeds $200. No ''no cap / unlimited earnings'' statement was found, so cap is unknown.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 27, 16, 19, 10, 9, 5, '{"compensation": "70% of platform profit plus 30% on Full Coverage, ~$20 average per booking, 365-day cookie \u2014 strongest published economics in the batch", "contact_access": "Open application plus a named dedicated account manager, but no published partnerships email was found", "credibility": "Rates and payout mechanics published in full on the brand''s own site and in its official affiliate terms", "niche_fit": "Car rental is a core travel-purchase category that attaches naturally to trip/UGC content", "opportunity_availability": "Free sign-up in minutes, open to travel blogs, sites and apps", "ugc_evidence": "Official page carries multiple testimonials from travel bloggers and content creators using the program"}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('SafetyWing', 'https://safetywing.com', 'SafetyWing sells travel medical and health insurance built for digital nomads, remote workers and long-term travelers, and is headquartered in San Francisco. Its Ambassador Program is its affiliate program: registered ambassadors earn a fee promoting SafetyWing products via a unique link, with promotion explicitly welcomed on social media, video and blogs.', 'United States', 'published') returning id into bid;
