  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'SafetyWing Ambassador Program', 'https://safetywing.com/ambassador', 'https://intercom.help/safetywing/en/articles/9796053-the-ambassador-program', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://safetywing.com/ambassador', 'official_site', 'ambassador_program_page', 'Official Ambassador page fetched: ''Become a SafetyWing Ambassador''; earnings estimator based on audience size; states ''Our Ambassadors include content creators like Chelsea Kauai and Nomadic Matt, and websites like Travel Off Path'' and offers exclusive webinars, forums, events and workshops.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://intercom.help/safetywing/en/articles/9796053-the-ambassador-program', 'official_site', 'help_center_program_description', 'Official SafetyWing Help Center article fetched in full: ''Ambassadors are registered affiliates who earn a fee by promoting SafetyWing products... All you have to do is create an account and answer a few questions about yourself. It should only take you a few minutes.'' Promotion allowed on ''any social media, personal website, video, or blogging platform''; payments made within the first ten working days of the new month.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.affiliates-directory.com/websites/safetywing', 'listing', 'commission_rate_listing', 'Affiliate directory listings quote SafetyWing''s own program wording: a flat affiliate fee ''currently benchmarked at approximately 10% of the total premium amount'' on completed applications via the referral link, recurring on purchases/renewals within a 364-day window, $10 minimum payout. The 10% rate itself was not printed on the fetched safetywing.com pages, hence publicly_reported confidence for the rate.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 28, 18, 16, 8, 9, 5, '{"compensation": "~10% of premium, recurring on renewals for up to 364 days per referral \u2014 one conversion can pay repeatedly; rate is benchmark wording, not guaranteed", "contact_access": "Direct open application on the brand''s own site; no published partnerships email found", "credibility": "Program, join flow and pay timing confirmed on SafetyWing''s own site and Help Center", "niche_fit": "Travel/nomad insurance is a staple recommendation in travel UGC and long-stay content", "opportunity_availability": "Sign-up takes a few minutes per the Help Center, with no follower minimum published", "ugc_evidence": "Official page names working creator ambassadors (Chelsea Kauai, Nomadic Matt) and the Help Center explicitly invites social/video/blog promotion"}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Sand Cloud', 'https://www.sandcloud.com/', 'Sand Cloud makes sustainably made beach towels, apparel, and accessories and donates 10% of profits to ocean cleanup and animal rescue organizations. Its official Ambassador Program is a hand-selected group of ocean lovers who apply, receive an exclusive discount code and custom link, and share on social (IG, TikTok, etc.) to start earning.', 'United States', 'published') returning id into bid;
