  insert into public.brands (name, website, description, country, status) values ('Fitbod', 'https://fitbod.me/', 'Fitbod is a strength training app that generates workouts based on the equipment you have, the muscles you have recently trained and your progress, with logging, form videos and integration with Apple Watch and other wearables. It runs on a subscription. Its affiliate program pays recurring commission for the first 12 months on referred subscriptions.', 'United States', 'published') returning id into bid;
