  insert into public.brands (name, website, description, country, status) values ('REP Fitness', 'https://repfitness.com/', 'REP Fitness is a US home-gym equipment brand. Its official affiliate page offers commission-based payouts, an exclusive discount on acceptance, and one-on-one contact with a representative, for affiliates with a health and/or fitness-oriented blog, vlog, website or social platform.', 'United States', 'published') returning id into bid;
