  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://repfitness.com/pages/affiliate-program-rep-fitness', 'official_site', 'affiliate_program_page', 'Official REP page: commission-based payouts, exclusive discount on acceptance, cookies/IPs stored up to 21 days, US-only new affiliates, fitness blog/vlog/social required, PayPal required, $100 commission threshold paid monthly, $1,500 sales over rolling 6 months to remain active, Sign Up link to repfitness.superfiliate.com.', 'verified', now());
