  insert into public.brands (name, website, description, country, status) values ('Outdoorsy', 'https://www.outdoorsy.com', 'Outdoorsy is a peer-to-peer RV rental marketplace headquartered in Austin, Texas, connecting RV owners with renters. Its affiliate program pays a flat bounty per referred renter''s first confirmed booking and per RV owner who completes a listing, tracked over a 30-day attribution cookie via AvantLink, CJ or HasOffers (Tune).', 'United States', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'travel'), true);
  insert into public.brand_contacts (brand_id, contact_type, email, contact_url, source_url, verification_status, last_verified_at) values (bid, 'creator_application', null, 'https://www.outdoorsy.com/affiliate', 'https://www.outdoorsy.com/affiliate', 'verified', now());
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'AvantLink / CJ / HasOffers (Tune)', null, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://www.outdoorsy.com/affiliate-terms.', 'https://www.outdoorsy.com/affiliate', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Outdoorsy Affiliate Program — $60 flat per booking or RV listing', 'https://www.outdoorsy.com/affiliate', 'https://www.outdoorsy.com/affiliate', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.outdoorsy.com/affiliate-terms', 'official_site', 'affiliate_terms', 'Official Affiliate Terms fetched in full: enrollment is by online application via the Outdoorsy Affiliate Program page; commission is paid when a referred renter''s first booking is confirmed and when an RV owner completes listing; 30-day attribution cookie; automated payments via AvantLink, CJ or HasOffers once the affiliate reaches a $100 minimum balance. The terms do not state the dollar amount.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.outdoorsy.com/affiliate', 'official_site', 'affiliate_program_page', 'Official affiliate page: ''Through the Outdoorsy Affiliate Program, you can help us achieve this mission by referring RV owners and renters, while earning lucrative commissions for every referral!'' and ''The Outdoorsy Affiliate Program is currently run on the HasOffers (Tune) and AvantLink Affiliate Networks.''', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.travelpayouts.com/blog/best-outdoor-affiliate-programs/', 'listing', 'flat_bounty_listing', 'Flat bounty (not a percentage): multiple independent listings agree on a $60 base commission per completed booking or new RV listing — Travelpayouts (''$60 or more per booking or RV owner listing'', 30-day cookie via AvantLink, also HasOffers/Tune), Admitad''s program roundup (''$60+'') and GetLasso (''$80 per successful booking and listing'' — higher figure, treated as unverified). Because the published pay is a flat $60 per action, commission_rate is null.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 26, 14, 18, 8, 8, 5, '{"compensation": "Flat $60 per confirmed first booking or completed owner listing is a high per-action bounty for travel; amount comes from network listings, not Outdoorsy''s own terms", "contact_access": "Open application via the official affiliate page and three major networks; no published partnerships email found", "credibility": "Program mechanics, cookie and payout threshold verified in Outdoorsy''s own published Affiliate Terms", "niche_fit": "RV/road-trip rentals are a strong, visual travel niche for UGC creators", "opportunity_availability": "Joinable through AvantLink, CJ or Tune with a 30-day cookie and $100 payout threshold", "ugc_evidence": "Program is pitched to content creators on network roundups and pays on both sides of the marketplace, but the official pages are website/affiliate-oriented rather than creator-branded"}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Airalo', 'https://www.airalo.com', 'Airalo is an eSIM marketplace founded in 2019 with its operational headquarters in Singapore, selling local, regional and global data plans for 200+ destinations. Its affiliate program, run through Impact, is explicitly positioned for creators, influencers and bloggers who earn commission on every eSIM bought through their links.', 'Singapore', 'published') returning id into bid;
