  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Airalo Affiliate Program (via Impact)', 'https://blog.partners.airalo.com/blog/airalo-partners-guide-to-esim-partnership-solution', 'https://blog.partners.airalo.com/blog/airalo-partners-guide-to-esim-partnership-solution', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://blog.partners.airalo.com/blog/airalo-partners-guide-to-esim-partnership-solution', 'official_site', 'partner_program_description', 'Official Airalo Partners blog: ''Perfect for creators, influencers, and bloggers, the Affiliate Program allows you to earn commissions while sharing affordable travel solutions with your audience... Airalo affiliates gain access to Impact, a user-friendly platform that makes creating and tracking commission links easy'' with pre-designed marketing materials and automatic tracking links.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://blog.partners.airalo.com/blog/benefits-of-becoming-airalo-affiliate', 'official_site', 'affiliate_benefits_page', 'Official Airalo Partners post: ''Whether you''re a travel blogger, deal site, YouTuber, or social media influencer, you have the power to provide your followers with an affordable, hassle-free way to stay connected when they travel''; affiliates share a link and earn a commission for each successful referral, with sign-up via Airalo Partners. Airalo calls it ''the largest in the eSIM industry'' — a size claim, not a creator count, so saturation stays unknown.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://affilmap.com/p/airalo/', 'listing', 'commission_rate_listing', 'Listings quoting Airalo''s own Impact program wording: ''Standard commission rate 10% on the final sale value (after discounts); rates may vary by promotional method'' — one-time per sale, manual approval, worldwide, via Impact; paid monthly with a $15 minimum via bank/PayPal. The separate $3 Airmoney credit is a consumer refer-a-friend perk, not the affiliate program.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 27, 17, 15, 7, 8, 5, '{"compensation": "Standard 10% per sale via Impact is published, but on low-priced eSIM plans the per-sale dollar amount is small and one-time", "contact_access": "Application routed through Airalo Partners/Impact; no published partnerships email found on the fetched pages", "credibility": "Program structure confirmed on Airalo''s own Partners blog; rate wording quoted from Airalo''s own Impact program terms by two independent listings", "niche_fit": "eSIM data is a near-universal travel purchase that fits almost any travel creator''s content", "opportunity_availability": "Open application through Impact with manual review; no follower minimum published", "ugc_evidence": "Official partner pages name travel bloggers, YouTubers and Instagram/social influencers as the target affiliate types, with stories/reels promotion guidance"}'::jsonb);
