  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 27, 15, 16, 7, 9, 4, '{"compensation": "Published 10% per sale with 30-day cookie", "contact_access": "No email published; page invites questions to Lab6 Media and links both signup programs", "credibility": "Program announced by its affiliate agency Lab6 Media with network, rate and cookie stated", "niche_fit": "Premium activewear/streetwear directly in fitness-fashion UGC niche", "opportunity_availability": "Open Impact signup links for both AU/NZ and international/US creators", "ugc_evidence": "Two regional Impact programs explicitly recruiting affiliates to promote its activewear"}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Ancient Nutrition', 'https://ancientnutrition.com', 'Supplement brand specializing in holistic, paleo and keto-friendly superfood supplements — including Bone Broth Protein, Collagen Peptides, herbal supplements and probiotics — built around nutrient-dense superfoods, modern science and a stated commitment to organic regenerative farming, and associated with Dr. Josh Axe.', null, 'published') returning id into bid;
