  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Ancient Nutrition Affiliate Program & Paid UGC Program (Aspire)', 'https://ancientnutrition.aspireiq.com', 'https://www.linkedin.com/company/ancient-nutrition?trk=public_jobs_jserp-result_job-search-card-subtitle', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.linkedin.com/company/ancient-nutrition?trk=public_jobs_jserp-result_job-search-card-subtitle', 'listing', 'affiliate', 'Ancient Nutrition''s official LinkedIn company post (published 2026-11-19) states: ''Over 100 creators have joined Ancient Nutrition''s affiliate program since our August launch'', affiliates receive a welcome kit with best-selling products and merch, ''Up to 25% commission as you grow through our tiers'', brand education and a creator community, and routes applications through ''Create with Ancient Nutrition'' at ancientnutrition.aspireiq.com.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.linkedin.com/company/ancient-nutrition?trk=public_jobs_jserp-result_job-search-card-subtitle', 'listing', 'ugc_collab', 'The same official LinkedIn post says the brand is looking for wellness creators, moms, coaches and trainers, and adds: ''Love creating content behind the scenes? Our paid UGC program is also accepting applications on a rolling basis.''', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.creator-hero.com/blog/top-20-best-us-health-wellness-influencer-affiliate-programs', 'listing', 'affiliate', 'Creator Hero''s influencer affiliate roundup lists Ancient Nutrition at 15% commission per sale with free product samples, exclusive promotions, early access to launches and a 90-day cookie, seeking influencers in the paleo, keto and holistic health niches.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://katalys.com/industries/collagen-affiliate-programs/', 'listing', 'general', 'Katalys lists Ancient Nutrition at 15% CPS among its top collagen affiliate programs for 2026, describing high-quality superfood supplements combining ancient wisdom with modern science and a commitment to organic regenerative farming.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 28, 19, 16, 9, 9, 5, '{"niche_fit": "Collagen, probiotics, bone broth protein and herbal supplements for gut, skin and joint health \u2014 squarely in the supplements/gut-health UGC niche.", "ugc_evidence": "Both an affiliate program recruiting wellness creators and a separate paid UGC program accepting rolling applications, announced on the brand''s own LinkedIn page.", "compensation": "Published 15% base commission (Creator Hero / Katalys) rising to up to 25% through tiers per the brand''s own post; no cap statement was published anywhere fetched, so cap is unknown.", "contact_access": "A dedicated creator application route via Aspire linked from the brand''s official post, but no published partnerships email was verified.", "opportunity_availability": "Actively recruiting now \u2014 ''Apply now to get set up ahead of the holiday season'' \u2014 plus rolling paid UGC applications.", "credibility": "Established category leader in natural health supplements with regenerative-farming positioning and Dr. Josh Axe association, per multiple independent listings."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Mito Red Light Therapy', 'https://mitoredlight.com', 'Scottsdale, Arizona-based red light therapy brand selling red light therapy devices and skincare, positioned around health, wellness and performance. Its affiliate terms list its address as 9319 N 94th Way #400, Scottsdale, AZ 85258 and invite creators, bloggers and wellness professionals to promote its devices and skincare through a unique affiliate link.', 'United States', 'published') returning id into bid;
