  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Mito Red Light Affiliate Program', 'https://mitoredlight.com/pages/affiliate-program-agreement', 'https://mitoredlight.com/pages/affiliate-program-agreement', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://mitoredlight.com/pages/affiliate-program-agreement', 'official_site', 'affiliate', 'Mito Red Light''s official Affiliate Program Terms (updated March 30, 2026) state affiliates receive a unique link, a 5% customer discount, 10% commission on device sales and 20% commission on skincare sales, with a 7-day cookie, payout 60 days after purchase, a $200 minimum and at least two completed sales, via Social Snowball or other platforms. No uncapped / no-cap statement appears in the fetched terms, so commission_cap is unknown.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://mitoredlight.com/pages/affiliate-program-agreement', 'official_site', 'ugc_collab', 'The same terms state the program is intended for ''Content creators (UGC, influencers)'', website owners, bloggers, email publishers and professionals such as estheticians, chiropractors and wellness practitioners, with approved channels including Instagram, YouTube and TikTok. Coupon/deal sites are excluded and routed separately via Impact.', 'verified', now());
