  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.crowdcow.com/affiliate', 'official_site', 'affiliate', 'Crowd Cow''s official ''Become a Crowd Cow Partner'' page (search-crawled; direct open hit a 429 rate limit) says it is ''looking to partner with influencers, publishers, customers and foodies'', offers ''best-in-class commissions on every order'', Cow Cash for free product, bonuses, and paid promotion of partner content, using Impact tracking links, and publishes affiliates@crowdcow.com. Its FAQ asks ''Is there a maximum I can earn in commission?'' but the answer text was not in the fetched material, so commission_cap is recorded as unknown, NOT uncapped.', 'publicly_reported', now());
