  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://account.opositiv.com/pages/creator-terms-conditions-guidelines', 'official_site', 'affiliate', 'O Positiv''s official Affiliate Terms and Conditions (last updated May 23, 2024) state affiliates must apply ''through the appropriate social media channels (e.g., TikTok Shop) [or via our website through our Ambassador Program]'', must be US residents aged 18+, and define Affiliate Content as wholly original user-generated content; commissions are based on product sales generated by that content and rates may vary by product.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://brandchamp.io/blog/customer-loyalty-programs-gummy-supplements/', 'listing', 'affiliate', 'BrandChamp''s breakdown of the O Positiv influencer program states members earn $5 for every sale made with their discount code (followers get 10% off), rising to $10 per sale in the VIP program after selling more than five bottles a month, and states: ''With this program, there''s no limit to how much money influencers can earn.''', 'publicly_reported', now());
