  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://opositiv.com/pages/about-us', 'official_site', 'general', 'O Positiv''s official About page states the brand was built to redefine women''s health, launching FLO PMS, the first-ever PMS gummy vitamin, followed by MENO, the first-ever menopause relief gummy, and URO Vaginal Probiotic, a best-seller in vaginal health.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 28, 17, 11, 13, 8, 5, '{"niche_fit": "Women''s gut, vaginal, hormonal and menopausal supplements \u2014 a core gut-health/wellness UGC niche with highly demonstrable products.", "ugc_evidence": "Official affiliate terms built entirely around creator UGC (original posts/videos, no generative AI without consent) plus an active TikTok Shop affiliate channel with sales incentive campaigns.", "compensation": "Published per-sale pay of $5, rising to $10 per sale for VIPs, with an explicit ''no limit to how much money influencers can earn'' statement; no percentage rate is published (official terms say rates vary by product), so the rate is recorded as null.", "contact_access": "A published affiliate team email (affiliates.tiktokshop@opositiv.com) on the brand''s own site plus two application routes (TikTok Shop and the website Ambassador Program).", "opportunity_availability": "Applications open via TikTok Shop or the website Ambassador Program for US creators 18+, per the official terms.", "credibility": "Founded 2018 in Los Angeles, category-defining first products (FLO PMS gummy, MENO gummy) and national brand recognition."}'::jsonb);
