  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://drinkkoia.com/pages/faqs', 'official_site', 'affiliate', 'Koia''s official FAQ answers ''Does Koia have an Affiliate program?'' with: ''Yes! With Koia''s affiliate program you''ll be rewarded with products and earn commissions in exchange for sharing Koia Online with your followers. Want in? Just click here and we''ll review within a few hours.'' The click-through routes to Koia''s Superfiliate portal (drinkkoiaaffiliate.superfiliate.com). No commission percentage, cap statement or creator count is published on the page, so rate is null, cap is unknown and saturation is unknown.', 'verified', now());
