  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 27, 17, 8, 10, 9, 4, '{"niche_fit": "Plant-based protein shakes and powders are a core functional-beverage UGC niche, with coffee and matcha flavors broadening creator angles.", "ugc_evidence": "The brand''s own FAQ explicitly frames the program around sharing Koia with followers in exchange for products and commissions \u2014 direct creator-facing evidence on an official page.", "compensation": "Products plus commissions are promised on the official page, but no percentage rate or cap statement is published anywhere fetched, so this stays low per the rubric.", "contact_access": "A direct application link on the official FAQ with review promised within a few hours, but no published partnerships email.", "opportunity_availability": "Applications are open now via the Superfiliate portal linked from the brand''s own site, with fast review.", "credibility": "Established national brand with distribution in over 35,000 U.S. retailers and certified vegan/non-GMO/kosher products."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Naked Nutrition', 'https://nakednutrition.com', 'Clean-label supplement brand founded in 2014 by former All-American track athlete Stephen Zieminski, built on minimal-ingredient formulas with nothing artificial — starting with five single-ingredient products including Naked Whey and growing to 100+ products spanning protein powders, vegan protein, collagen, creatine, gut health and overnight oats, all third-party tested.', 'United States', 'published') returning id into bid;
