  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Naked Nutrition Affiliate Program', 'https://nakednutrition.com/pages/affiliates', 'https://nakednutrition.com/pages/affiliates', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://nakednutrition.com/pages/affiliates', 'official_site', 'affiliate', 'Naked Nutrition''s official Affiliates page lists key benefits verbatim: ''1. Earn 10% commission rate 2. Cookie duration of 30 days 3. High website conversion rate and average order value 4. Strong repurchase rate within the 30 day cookie window 5. Access to special discount codes and new product launches'', invites applicants to ''Join a network of premium websites and creators'' earning on both its website and Amazon, and provides ''Apply For Naked Nutrition Affiliate Program'' and ''Apply For Amazon Affiliate Program'' routes.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://getlasso.co/niche/supplements/', 'listing', 'affiliate', 'GetLasso''s supplements roundup lists Naked Nutrition at 10% per sale with a 30-day cookie on the AvantLink network and a $50 payout threshold, describing clean, transparent-label protein powders and supplements for health enthusiasts.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://nakednutrition.com/pages/about-us', 'official_site', 'general', 'Naked Nutrition''s official About page states Stephen Zieminski founded the brand in 2014 starting with five single-ingredient supplements including best-selling Naked Whey, that it has grown to 100+ products, and lists standards including no artificial sweeteners, gluten free, soy free, GMO free and third-party testing for heavy metals.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 27, 14, 12, 9, 8, 5, '{"niche_fit": "Protein, collagen, creatine and gut-health supplements with short ingredient lists \u2014 ideal for recipe, routine and ''what I take'' UGC formats.", "ugc_evidence": "The official program page explicitly recruits ''premium websites and creators'' and offers discount codes and launch access, though no separate UGC-specific program details are published.", "compensation": "A published 10% commission rate with a 30-day cookie on the brand''s own page; no cap statement was published anywhere fetched, so cap is unknown.", "contact_access": "Two public application routes on the official affiliates page (direct and Amazon), but no published partnerships email was verified.", "opportunity_availability": "Open application today through the brand''s own affiliates page and its Amazon affiliate route.", "credibility": "Operating since 2014 with 100+ products, third-party heavy-metal testing and coverage in outlets such as GQ, Men''s Journal and Healthline reported by reviewers."}'::jsonb);
