  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.hatch.co/affiliate', 'official_site', 'affiliate', 'Hatch''s official affiliate page states: ''4% commission on Rest and Restore sales'', a 30-day cookie window, opportunity for increased rates for high performers, and a dedicated account management team, with sign-up via its Apply Now link to Impact. No uncapped / no-cap statement appears on the fetched page, so commission_cap is unknown.', 'verified', now());
