  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 29, 15, 7, 9, 9, 4, '{"niche_fit": "Pure sleep brand \u2014 Rest and Restore devices built around rest and feeling well-rested \u2014 the closest possible fit for the sleep slice.", "ugc_evidence": "A dedicated social-creator route on ShopMy/LTK with free products for select partners, plus photo/review content instructions on the official page.", "compensation": "A published rate, but only 4% on Rest and Restore sales on the main program (higher via ShopMy/LTK for select partners, amount not published) and no uncapped statement found.", "contact_access": "A dedicated official affiliate page with an Apply Now route and a dedicated account management team, but no published partnerships email.", "opportunity_availability": "Open sign-up today via Impact, with an additional open social-creator route via ShopMy or LTK.", "credibility": "Well-known consumer sleep brand with a structured, network-run program and dedicated affiliate management."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Ice Barrel', 'https://icebarrel.com', 'US cold-therapy brand selling upright cold plunge barrels (Ice Barrel 300 and 500) and a chiller, made in the USA from recycled materials and backed by a limited lifetime warranty, for muscle recovery and wellness. It runs both an ambassador program and an affiliate program for cold-therapy advocates.', 'United States', 'published') returning id into bid;
