  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Ice Barrel Affiliate and Ambassador Program', 'https://icebarrel.com/pages/work-with-us', 'https://icebarrel.com/pages/work-with-us', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://icebarrel.com/pages/work-with-us', 'listing', 'affiliate', 'Ice Barrel''s official ''Work With Us'' page (as returned in search results) has separate ''Be an ambassador'' and ''Be an affiliate'' routes, stating: ''Help us spread the power of cold by joining our affiliate program on ShareASale and earn commissions on each sale you generate'', with an ''Apply now (via ShareASale)'' route.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://ui.awin.com/merchant-profile/82317', 'listing', 'affiliate', 'Ice Barrel''s Awin merchant profile states verbatim: ''We pay a 5% commission on sales with a 15-day cookie duration'' and ''please feel free to reach out to our affiliate team at affiliates@icebarrel.com''. No uncapped / no-cap statement was found in the fetched material, so commission_cap is unknown. Note: a direct fetch of this profile was rate-limited (429) in this run, so this evidence rests on the search-result extract.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://icebarrel.com/', 'official_site', 'general', 'Ice Barrel''s official homepage (as returned in search results) describes cold therapy products starting at $1,150, HSA/FSA eligible, made in the USA from medical-grade, recycled and BPA-free materials, with a limited lifetime warranty — supporting a high average order value behind the percentage rate.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 26, 13, 8, 13, 8, 4, '{"niche_fit": "Cold plunge / ice bath barrels are a core recovery modality for athletes and wellness creators \u2014 strong fit for the recovery slice.", "ugc_evidence": "Both an ambassador program (''building deep relationships with those who serve as our ambassadors'') and an affiliate program on the official Work With Us page, though no UGC-specific deliverables are published.", "compensation": "Published 5% commission on Awin (15-day cookie), modest as a percentage but on $1,150+ products; no uncapped statement found, and the ShareASale rate on the brand''s own page is not published.", "contact_access": "A published affiliate-team email (affiliates@icebarrel.com) on the network profile plus ambassador and affiliate application routes on the official site \u2014 top band per the rubric.", "opportunity_availability": "Affiliate applications open now via ShareASale/Awin and ambassador applications open on the official page.", "credibility": "Established US cold-therapy brand, made in USA with a limited lifetime warranty and HSA/FSA eligibility."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Native Pet', 'https://nativepet.com', 'Native Pet, founded in 2017 in St. Louis, Missouri by Dan Schaefer and Pat Barron, makes organic, limited-ingredient, vet-formulated supplements for dogs and cats — probiotics, hip and joint chews, pumpkin powder, omega oil, calming chews and The Daily — sold DTC and in 2,200+ Tractor Supply stores nationwide.', 'United States', 'published') returning id into bid;
