  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Superfiliate / Impact', 15, 'Commission cap: not stated in any published source found — needs review. Creator saturation: high (see evidence). Rate as reported by https://getlasso.co/affiliate/native-pet/.', 'https://nativepet.com/pages/affiliate-program', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Native Pet Affiliates + Ambassadors Program (Superfiliate)', 'https://nativepet.com/pages/affiliate-program', 'https://nativepet.com/pages/affiliate-program', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://nativepet.com/pages/affiliate-program', 'official_site', 'ugc_collab', 'Native Pet''s own affiliate-program page (opened directly) is a live Superfiliate portal application: it asks for the pet''s name, email and PayPal email, a chosen discount code, Instagram (required), TikTok and YouTube, pet age and allergies, and address — a creator-first application collecting social handles and paying via PayPal. The brand''s affiliate one-pager likewise links this page as its affiliate signup.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://static1.squarespace.com/static/5f57a5db19270a2fe560d10c/t/61afba99d96b7523fd2c04d7/1638906524122/Native+Pet+1pager.pdf', 'official_site', 'contact', 'Native Pet''s own affiliate one-pager says ''Please reach out to partners@nativepet.com'', links the affiliate programme page https://nativepet.com/pages/affiliate-program, and lists its socials: Facebook facebook.com/nativepet, Instagram instagram.com/thenativepet/, Pinterest thenativepet.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://getlasso.co/affiliate/native-pet/', 'listing', 'affiliate', 'Lasso lists Native Pet at up to 15% commission, 14-day cookie, $10 payout threshold; Acciyo''s roundup independently lists 15%. RATE CONFLICT: FlawlessMLM reports 20% on first orders via Impact with a 30-day cookie and minimal repeat-order commission — recorded rate is 15% (two sources) with the 20% first-order Impact claim noted here. No cap statement was found on any fetched page.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://universe.beacons.ai/brands/native-pet', 'listing', 'ugc_collab', 'Beacons Universe (updated 19 Nov 2026) counts 421 creators who have posted about Native Pet all-time, 50 in the last 30 days (104 mentions), and 39 sponsored posts in the last 12 months — direct evidence of HIGH creator saturation, so creator_saturation is ''high''.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://career.io/job/affiliate-coordinator-st-louis-native-pet-15346d8843dd8464888d0b37f6e8772a', 'listing', 'ugc_collab', 'Native Pet''s Affiliate Coordinator job post describes its DTC affiliate programme as focused on creators on Instagram, YouTube and TikTok, run day-to-day on Superfiliate (with GRIN), constantly sourcing and onboarding new affiliates, with an affiliate email inbox and a Discord ambassador community — a staffed, actively recruiting creator programme.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 28, 18, 14, 13, 9, 4, '{"compensation": "15% published by two listings; a conflicting 20% first-order Impact claim is noted, and no cap statement is published.", "contact_access": "Published partnerships email partners@nativepet.com on the brand''s own affiliate one-pager, plus a live official application portal and a Google Form route.", "credibility": "Founded 2017 in St. Louis, $17M raised (Series B $11M), full line in 2,200+ Tractor Supply stores.", "niche_fit": "Vet-formulated dog and cat supplements for gut, joint, calm and coat \u2014 everyday-routine pet UGC.", "opportunity_availability": "Applications open now on the brand''s own site, with the brand actively hiring to source and onboard new affiliates.", "ugc_evidence": "421 Beacons creators, 39 sponsored posts in 12 months, a staffed programme on Superfiliate/GRIN with a Discord ambassador community, and an application built around Instagram/TikTok/YouTube handles."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Ollie', 'https://www.myollie.com', 'Ollie (Ollie Pets Inc.), founded in 2016 in New York City, is a direct-to-consumer subscription brand selling fresh and baked human-grade dog food — personalised meal plans formulated with veterinary nutritionists and tailored to a dog''s breed, age, weight and activity — plus treats and supplements, donating a portion of proceeds to rescue shelters; it was acquired by Agrolimen in February 2026 and continues to operate independently.', 'United States', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'pets'), true);
  insert into public.brand_socials (brand_id, platform, handle, url) values (bid, 'instagram', 'ollie', 'https://www.instagram.com/ollie');
  insert into public.brand_contacts (brand_id, contact_type, email, contact_url, source_url, verification_status, last_verified_at) values (bid, 'creator_application', null, 'https://www.myollie.com/affiliate/', 'https://www.creator-hero.com/blog/ollie-affiliate-program-in-depth-review-pros-and-cons', 'needs_review', null);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Impact', null, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://www.creator-hero.com/blog/ollie-affiliate-program-in-depth-review-pros-and-cons.', 'https://www.myollie.com/affiliate/', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Ollie Affiliate Program (Impact) — $60 flat per new customer', 'https://www.myollie.com/affiliate/', 'https://www.creator-hero.com/blog/ollie-affiliate-program-in-depth-review-pros-and-cons', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.creator-hero.com/blog/ollie-affiliate-program-in-depth-review-pros-and-cons', 'listing', 'affiliate', 'Creator Hero''s in-depth review states Ollie affiliates earn a flat $60 commission per sale with a 30-day cookie via Impact Radius, joining via Ollie''s own affiliate page https://www.myollie.com/affiliate/ which routes to Impact; FlexOffers is listed at $48 per sale. Because the pay is a flat fee, not a percentage, commission_rate is null. RATE CONFLICT: one March 2026 roundup (affiliatemarketinggirl.io) claims 20% on first orders in-house — not corroborated by any other fetched source; the $60 flat figure is corroborated by Lasso, LinkWhisper, FunnelScene, Post Affiliate Pro and UpPromote.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://uppromote.com/affiliate-directory/ollie/', 'listing', 'affiliate', 'UpPromote''s Ollie directory entry confirms the program is hosted on Impact Radius, pays up to $60 flat per new-customer sale, 30-day cookie, US only, accepts pet blogs, social media, email and review sites, and explicitly rates TikTokers and pet content creators as highly suitable.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://universe.beacons.ai/brands/ollie-pets', 'listing', 'ugc_collab', 'Beacons Universe (updated 18 Nov 2026) counts 143 creators who have posted about Ollie Pets all-time, 9 in the last 30 days, with 19 sponsored posts in the last 12 months — an active creator programme, but far too many creators to evidence ''low'' saturation, so saturation is unknown.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.petfoodindustry.com/news-newsletters/pet-food-news/news/15816547/agrolimen-acquires-fresh-dog-food-brand-ollie', 'article', 'general', 'Petfood Industry reports Agrolimen acquired New York City-based Ollie (founded 2016, veterinary-backed fresh dog food with personalised plans) in February 2026, with Ollie continuing as an independent brand; Ollie''s own PR directs followers to Instagram @ollie and www.myollie.com.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 29, 17, 18, 8, 8, 5, '{"compensation": "Flat $60 per new-customer sale via Impact (30-day cookie) \u2014 the highest per-conversion payout in this group; one uncorroborated 20% claim is noted as a conflict, and no cap statement is published.", "contact_access": "A brand-owned affiliate landing page routing to Impact, but no published partnerships email on fetched pages.", "credibility": "Founded 2016, pioneer of fresh dog food, acquired by Agrolimen in 2026 reportedly for $600M+ while operating independently.", "niche_fit": "Premium fresh dog food built for feeding-time, unboxing and health-transformation pet content \u2014 core pets UGC.", "opportunity_availability": "Open to apply today via myollie.com/affiliate \u2192 Impact, US affiliates.", "ugc_evidence": "143 Beacons creators, 19 sponsored posts in 12 months, and Ollie runs creator videos as its own ads \u2014 documented, active creator use."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Branch Basics', 'https://branchbasics.com', 'Non-toxic cleaning brand founded in Texas by Allison Evans, Kelly Love and Marilee Nelson, built around a plant- and mineral-based Concentrate that dilutes into all-purpose, bathroom, laundry and other household cleaners under a ''Toss the Toxins'' healthy-home mission; products are human-safe, free of harmful preservatives, EWG Verified / MADE SAFE certified, sold direct-to-consumer and increasingly in retail including Target, with reported revenue of $40 million in 2023.', 'United States', 'published') returning id into bid;
