  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Awin / Superfiliate', 10, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://ui.awin.com/merchant-profile/90429?setLocale=da_DK.', 'https://branchbasics.com', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Branch Basics Ambassador Program (Superfiliate)', 'https://branchbasics.com', 'https://prpackage.com/brand-ambassador-programs/', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://ui.awin.com/merchant-profile/90429?setLocale=da_DK', 'listing', 'affiliate', 'Branch Basics'' own Awin merchant profile states verbatim: ''we are offering a 10% commission on sales with a 30 day cookie window'', with an AOV around $60, and says the brand wants ''to help publishers large and small monetize all their wonderful content''.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://prpackage.com/brand-ambassador-programs/', 'listing', 'ugc_collab', 'PRPackage''s ambassador directory (verified 26 Sep 2026 against branchbasics.com) lists a separate Branch Basics Ambassador Program running on Superfiliate: a 15% audience discount code at Ambassador level, then tiered commission of 5% / 10% / 15% / 20% at Bronze and higher tiers; applicants must be existing Branch Basics users in the US or Canada with 1,000+ followers and share at least one story set per month. NOTE: this tiered ambassador structure (up to 20%) sits alongside the flat 10% Awin rate — the two routes pay differently, and no single rate covers both.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.inc.com/christine-lagorio/why-branch-basics-stopped-selling-its-one-product.html', 'listing', 'general', 'Inc. profiles founders Allison Evans, Kelly Love and Marilee Nelson raising $1 million and rebranding as Branch Basics around a single cleaning solution; Brandiary reports the brand reached $40 million in revenue in 2023, and founder interviews note Target retail expansion — an established, scaled home brand.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 28, 17, 15, 9, 9, 5, '{"compensation": "A published 10% flat rate on the brand''s own Awin profile, with the ambassador track tiering up to 20% per the ambassador directory; no cap statement was found, so the cap is unknown.", "contact_access": "Two public application routes (Awin and the ambassador program via the brand''s site), but no published partnerships email was verified.", "credibility": "Scaled DTC brand with reported $40M 2023 revenue, national press (Inc.) and Target retail distribution.", "niche_fit": "Non-toxic cleaning concentrates and healthy-home products \u2014 a core home UGC niche (''clean with me'', toxin-free home content).", "opportunity_availability": "Both programs are joinable now; the ambassador track is open to creators with as few as 1,000 followers who already use the product.", "ugc_evidence": "Two live creator routes: an open Awin affiliate program plus a dedicated Ambassador Program on Superfiliate with a defined monthly story deliverable and a 1,000-follower entry bar aimed at small creators."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('BarkBox', 'https://www.barkbox.com', 'BarkBox, by BARK, Inc. (NYSE: BARK), founded in December 2011 in New York by Matt Meeker, Henrik Werdelin and Carly Strife, is the leading monthly subscription for dogs: themed BarkBox boxes (2 toys, 2 treats, 1 chew) and Super Chewer boxes for tough chewers, plus BARK Bright Dental and BARK Food, serving over two million dogs monthly through subscriptions and retail.', 'United States', 'published') returning id into bid;
