  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Impact / CJ Affiliate', null, 'Commission cap: not stated in any published source found — needs review. Creator saturation: high (see evidence). Rate as reported by https://barkboxaffiliateprogram.splashthat.com/.', 'https://www.barkbox.com/affiliate', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'BarkBox & Super Chewer Affiliate Program (Impact / CJ)', 'https://www.barkbox.com/affiliate', 'https://barkboxaffiliateprogram.splashthat.com/', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://barkboxaffiliateprogram.splashthat.com/', 'official_site', 'affiliate', 'BARK''s own affiliate programme page (opened directly) states the BarkBox & Super Chewer programme ''works with hundreds of marketing affiliates'', pays a flat tiered monthly CPA — 1–100 subscriptions = $15, 101–200 = $17, 201+ = $19 per subscription, tiers resetting monthly — with BarkShop on a CPS revshare, and invites applications (''Not on Impact Radius?'' section). Because pay is flat per subscription, commission_rate is null. CONFLICTS: the same page states a 30-day tracking cookie, while CJ Affiliate listings report a 7-day cookie and $18 per BarkBox / $20 per Super Chewer or Bright Dental signup plus 10% on BARK Food (Lasso: $20.80 per sale via CJ, $50 threshold) — network terms differ by route and are noted here.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.bravodm.com/brands/barkbox', 'listing', 'ugc_collab', 'BravoDM (checked Oct 2026, not affiliated with BARK) lists the BARK Affiliate and Creator Program at barkbox.com/affiliate via Impact, open to affiliates and creators who love dogs to promote BarkBox and Super Chewer, and gives BARK''s Instagram as @barkbox. BARK''s own giveaway rules give instagram.com/barkbox and facebook.com/barkbox, and its TikTok posts are under @barkbox.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.inc.com/vanna-le/how-this-dog-subscription-company-disrupted-the-66-billion-pet-industry.html', 'article', 'ugc_collab', 'Inc. reports BARK had about 500 dogs ''on payroll'' as influencers, ~6 million social followers, and that influencers reach out constantly with content submissions; a later case study notes #barkbox has been mentioned over 4 million times on Instagram — direct evidence of HIGH creator saturation.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://en.wikipedia.org/wiki/BarkBox', 'article', 'general', 'Wikipedia: BarkBox launched December 2011 by Carly Strife, Matt Meeker and Henrik Werdelin, HQ New York, a monthly subscription providing dog products, services and experiences; BARK serves over two million dogs monthly through BarkBox and Super Chewer subscriptions and retail.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 29, 18, 13, 8, 8, 5, '{"compensation": "Flat tiered CPA on the brand''s own page ($15/$17/$19 per subscription by monthly volume); CJ listings differ ($18\u2013$20 signups, 10% on BARK Food) and cookie terms conflict (30-day on brand page vs 7-day on CJ) \u2014 no cap statement published.", "contact_access": "A dedicated barkbox.com/affiliate creator route via Impact, but no published partnerships email on fetched pages.", "credibility": "Founded 2011, publicly traded BARK, Inc. (NYSE: BARK), over two million dogs served monthly plus 40k+ retail stores.", "niche_fit": "The original dog unboxing subscription \u2014 toys, treats and themed boxes are peak pet UGC material.", "opportunity_availability": "Open application via Impact/CJ today; the brand states it works with hundreds of affiliates and is open to almost all partner types.", "ugc_evidence": "~500 influencer dogs on payroll per Inc., #barkbox mentioned 4M+ times on Instagram, and a named Affiliate and Creator Program via Impact."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Sensate', 'https://www.getsensate.com', 'Wellness-technology company founded in 2016 and based in Taunton, United Kingdom, selling a wearable vagus-nerve toning device that uses patented infrasonic resonance (low-frequency sound waves and soundscapes, placed on the sternum) with a companion app to reduce stress and improve sleep, featured in The Times, Psychology Today, Men''s Journal and Women''s Health.', 'United Kingdom', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'technology'), true);
  insert into public.brand_contacts (brand_id, contact_type, email, contact_url, source_url, verification_status, last_verified_at) values (bid, 'partnerships', 'partners@getsensate.com', null, 'http://www.getSENSATE.com/pages/affiliate', 'verified', now());
  insert into public.brand_contacts (brand_id, contact_type, email, contact_url, source_url, verification_status, last_verified_at) values (bid, 'creator_application', null, 'https://af.uppromote.com/getsensate/register', 'http://www.getSENSATE.com/pages/affiliate', 'verified', now());
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'UpPromote', 10, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by http://www.getSENSATE.com/pages/affiliate.', 'https://af.uppromote.com/getsensate/register', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Sensate Affiliate Program', 'https://af.uppromote.com/getsensate/register', 'http://www.getSENSATE.com/pages/affiliate', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'http://www.getSENSATE.com/pages/affiliate', 'official_site', 'affiliate', 'Sensate''s official affiliate page states: ''10% for you, 10% discount for your community'' — affiliates earn 10% commission on products bought with their unique discount code, applications reviewed within seven days, paid around the 15th of each month by UK bank transfer or PayPal elsewhere. No cap on earnings is stated anywhere on the page, so commission_cap is unknown.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'http://www.getSENSATE.com/pages/affiliate', 'official_site', 'contact', 'The same page publishes partners@getsensate.com as the partner liaison email and links direct sign-up at https://af.uppromote.com/getsensate/register (UpPromote), with marketing materials and a partner liaison provided on approval.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'http://www.getSENSATE.com/pages/affiliate', 'official_site', 'ugc_collab', 'The page carries a named affiliate case study (holistic health coach Lauren Vaknine describing promoting Sensate on her podcast and to clients), showing real creator/affiliate promotion, but no creator-count evidence was found, so creator_saturation is unknown.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.cbinsights.com/company/sensate-1', 'listing', 'general', 'CB Insights describes Sensate as a wellness technology company founded in 2016, based in Taunton, United Kingdom, offering a wearable device using infrasonic waves and soundscapes for relaxation and sleep with a mobile app.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 26, 16, 12, 14, 9, 4, '{"compensation": "A clean published 10% commission plus a 10% community discount on the brand''s own page; no cap statement, so not top band.", "contact_access": "A published partner-liaison email (partners@getsensate.com) plus a direct sign-up link on the official page \u2014 top band.", "credibility": "Founded 2016, UK-based, with national press features named on its own page (The Times, Women''s Health, Men''s Journal).", "niche_fit": "A wearable stress/sleep tech device with an app \u2014 squarely technology, with strong wellness-creator crossover.", "opportunity_availability": "Open sign-up today via UpPromote with review promised within seven days.", "ugc_evidence": "A structured affiliate program with discount codes, creative library and a published named-affiliate case study."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Smalls', 'https://www.smalls.com', 'Smalls, founded in 2017 in New York by Matt Michaelson and Calvin Bohn, is the first cat-only direct-to-consumer fresh food brand: gently cooked, human-grade, protein-packed fresh and freeze-dried cat food, portioned to each cat''s calorie needs and delivered by subscription, now also in retail — a deliberately cat-first brand in a dog-dominated pet market.', 'United States', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'pets'), true);
  insert into public.brand_socials (brand_id, platform, handle, url) values (bid, 'instagram', 'smallsforcats', 'https://www.instagram.com/smallsforcats');
  insert into public.brand_contacts (brand_id, contact_type, email, contact_url, source_url, verification_status, last_verified_at) values (bid, 'creator_application', null, 'https://linkclicky.com/affiliate-program/smalls/', 'https://linkclicky.com/affiliate-program/smalls/', 'needs_review', null);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Impact', 35, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://linkclicky.com/affiliate-program/smalls/.', 'https://linkclicky.com/affiliate-program/smalls/', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Smalls Affiliate Program (Impact) — per trial purchase', 'https://linkclicky.com/affiliate-program/smalls/', 'https://linkclicky.com/affiliate-program/smalls/', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://linkclicky.com/affiliate-program/smalls/', 'listing', 'affiliate', 'LinkClicky lists Smalls on Impact at 35% commission per successful trial purchase, regions ALL. RATE CONFLICT: Lasso lists 24% per trial purchase with a 30-day cookie. The two published trial rates (35% vs 24%) do not agree and no brand-owned program page publishing a rate was fetched, so commission_rate is recorded as 35 from the Impact listing with the conflict stated here, and compensation is scored conservatively.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.skimlinks.com/insights/pet-affiliate-programs/', 'listing', 'affiliate', 'Skimlinks'' pet affiliate roundup describes Smalls as a DTC fresh, gently cooked, human-grade cat food subscription, ''voted #1 healthiest cat food'', with its affiliate program available in the United States — corroborating a live, joinable program.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://universe.beacons.ai/brands/smalls', 'listing', 'ugc_collab', 'Beacons Universe (updated 18 Nov 2026) counts 114 creators who have posted about Smalls all-time, 9 in the last 30 days and 7 sponsored posts in the last 12 months — active creator activity, insufficient evidence for ''low'' saturation, so saturation is unknown.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.businesswire.com/news/home/20230328005140/en/Smalls-Closes-%2419-Million-Round-to-Become-Market-Leader-in-Cat-Focused-Recession-Proof-Pet-Category', 'article', 'general', 'Smalls'' own Business Wire release: founded 2017 as the first cat-first brand, raised $19M (2023), had generated 8-figures in sales feeding more than 100,000 cats, entering retail; it directs readers to www.smalls.com and Instagram @smallsforcats. Inc. later reported Smalls reached $100M annual revenue.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 28, 16, 16, 7, 8, 4, '{"compensation": "Published trial-purchase rates are high (35% on Impact per LinkClicky) but conflict with Lasso''s 24%, and no cap statement is published \u2014 scored down for the conflict.", "contact_access": "Joinable via the Impact listing only; no published partnerships email or brand-owned program page was fetched.", "credibility": "Founded 2017, $34M+ raised, 100,000+ cats fed, reported $100M annual revenue and new retail distribution.", "niche_fit": "Cat-only fresh food \u2014 an underserved, high-engagement corner of pet UGC dominated by dog brands.", "opportunity_availability": "Program live and joinable in the US via Impact/Skimlinks today.", "ugc_evidence": "114 Beacons creators with recent sponsored posts, plus paid social-series/podcast creator deals reported by Inc."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Who Gives A Crap', 'https://whogivesacrap.org', 'B Corp certified social enterprise founded in Melbourne, Australia in 2010, describing itself as the world''s largest D2C toilet paper company, selling recycled and bamboo toilet paper, paper towels and tissues in playful packaging and donating 50% of profits to non-profits delivering clean water and sanitation; it raised $30.7 million in a 2021 Series A and was named to TIME''s TIME100 Companies list in 2026.', 'Australia', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'home'), true);
  insert into public.brand_socials (brand_id, platform, handle, url) values (bid, 'instagram', 'whogivesacraptp', 'https://www.instagram.com/whogivesacraptp');
  insert into public.brand_contacts (brand_id, contact_type, email, contact_url, source_url, verification_status, last_verified_at) values (bid, 'creator_application', null, 'https://ui.awin.com/merchant-profile/66840/commission-groups', 'https://ui.awin.com/merchant-profile/66840/commission-groups', 'needs_review', null);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Awin', 12, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://ui.awin.com/merchant-profile/66840/commission-groups.', 'https://ui.awin.com/merchant-profile/66840', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Who Gives A Crap Affiliate Programme — Influencer and Blogger Group (Awin)', 'https://ui.awin.com/merchant-profile/66840', 'https://ui.awin.com/merchant-profile/66840/commission-groups', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://ui.awin.com/merchant-profile/66840/commission-groups', 'listing', 'affiliate', 'The brand''s Awin (AU) programme publishes a full commission-group table with a 30-day cookie: the ''Influencer and Blogger'' and ''Content'' groups earn 12% CPA on new customers, while the Standard Rate is 2% on new customers and the return-customer (default) rate is 1% across groups. RATE STRUCTURE NOTE: the headline 12% applies only to influencer/content partners on new-customer sales; standard affiliates get 2%/1%.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://ui.awin.com/merchant-profile/66844?setLocale=pl_PL', 'listing', 'affiliate', 'A separate Awin (US) programme listing shows a much lower 2% default commission rate for new customers with a 30-day cookie — US creators should confirm which programme and commission group they are placed in before relying on the 12% AU influencer rate.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://us.whogivesacrap.org/pages/about-us?variation=A', 'official_site', 'general', 'The brand''s official US About page confirms the model: rolls made from recycled fibres or bamboo and 50% of profits donated toward ensuring everyone has access to clean water and a toilet.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://parsers.vc/startup/whogivesacrap.org/', 'listing', 'general', 'Parsers VC lists Who Gives A Crap as Melbourne, Australia-based, founded 2010, with $30.7M raised, and reports its April 2026 naming to TIME''s TIME100 Companies industry leaders in social good, with over $14 million in total donations announced.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 26, 15, 13, 8, 8, 5, '{"compensation": "12% on new-customer sales for influencer/content groups is strong, but it drops to 1% on returning customers and the standard rate is only 2%, so blended earnings will run well below the headline.", "contact_access": "A public Awin application route with full published commission tables, but no published partnerships email was verified.", "credibility": "B Corp social enterprise operating since 2010, $30.7M Series A, TIME100 Companies recognition and 50%-of-profits donation model stated on its own site.", "niche_fit": "Everyday household paper essentials with a strong sustainability and humour angle \u2014 a proven fit for home and eco-living UGC.", "opportunity_availability": "The programme is live and joinable on Awin in both AU and US variants today.", "ugc_evidence": "Awin publishes a dedicated ''Influencer and Blogger'' commission group distinct from standard affiliates \u2014 direct evidence the programme is structured for creators, not just coupon publishers."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('MOFT', 'https://www.moft.com', 'MOFT (Mobile Office for Travelers), founded in 2017 and headquartered in Sunnyvale, California, makes origami-inspired, minimalist portable productivity accessories — invisible laptop stands, phone stands and wallets, tablet stands and MagSafe accessories — for smartphones, tablets and laptops, selling through its own store and distributors to over one million users.', 'United States', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'technology'), true);
  insert into public.brand_contacts (brand_id, contact_type, email, contact_url, source_url, verification_status, last_verified_at) values (bid, 'creator_application', null, 'https://www.moft.com/en-ar/pages/influencer-affiliate-program', 'https://www.moft.com/en-ar/pages/influencer-affiliate-program', 'verified', now());
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, null, 10, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://getlasso.co/affiliate/moft/.', 'https://www.moft.com/en-ar/pages/influencer-affiliate-program', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'MOFT Influencer Affiliate Program', 'https://www.moft.com/en-ar/pages/influencer-affiliate-program', 'https://www.moft.com/en-ar/pages/influencer-affiliate-program', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.moft.com/en-ar/pages/influencer-affiliate-program', 'official_site', 'affiliate', 'MOFT''s official site publishes a dedicated ''Influencer Affiliate Program'' page and a separate ''Affiliate Program'' page (both confirmed live in search results from moft.com). HONEST LIMIT: the page body is JavaScript-rendered and returned empty on text fetch, so no rate, email or cap statement could be read from the official page itself — commission_cap is therefore unknown.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://getlasso.co/affiliate/moft/', 'listing', 'affiliate', 'Lasso''s MOFT listing gives the program as Tech category at 10% per sale and describes the standard join flow (application, approval in a few days, affiliate dashboard and referral link). This 10% is third-party reported only — it is NOT confirmed on a readable official page, hence commission_rate rests on this listing.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://brandwiki.lazada.sg/moft/', 'listing', 'general', 'Brand Wiki describes MOFT as founded in 2017, established in Silicon Valley, California (engineering/manufacturing in Shenzhen), an acronym for Mobile Office for Travelers, with over one million users and distribution via its own store, Apple retail channels for select items and authorized distributors.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 28, 14, 12, 8, 8, 4, '{"compensation": "10% per sale per the Lasso listing; discounted because the rate could not be read on MOFT''s own (JS-rendered) page and no cap terms are published.", "contact_access": "A dedicated official program page with a join route, but no published partnerships email was verified \u2014 mid-range.", "credibility": "Founded 2017, million-plus users, Kickstarter-proven launches and Apple-channel distribution for select products.", "niche_fit": "Phone/laptop stands, wallets and desk-tech accessories are core everyday-tech UGC territory \u2014 desk-setup and travel-tech creators especially.", "opportunity_availability": "Program page is live on moft.com today with an application route.", "ugc_evidence": "A program explicitly named and built for influencers on the brand''s own site, not just a publisher network listing."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('XREAL', 'https://www.xreal.com', 'Consumer AR glasses company founded in 2017 in Beijing, China by Dr. Chi Xu (formerly Nreal), designing, developing and marketing lightweight AR/display eyewear — the XREAL Air and One series, Beam Pro companion and Project Aura Android XR glasses — that act as a large portable virtual screen for phones, PCs and consoles.', 'China', 'published') returning id into bid;
