  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, null, null, 'Commission cap: not stated in any published source found — needs review. Creator saturation: low (see evidence). Rate as reported by https://www.xreal.com/us/visionaries.', 'https://www.xreal.com/us/visionaries', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'XREAL Visionaries Creator Program', 'https://www.xreal.com/us/visionaries', 'https://www.xreal.com/us/visionaries', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.xreal.com/us/visionaries', 'official_site', 'ugc_collab', 'XREAL''s official Visionaries creator program page recruits ''Authentic Storytellers'', ''XREAL Gurus'' and ''Passionate Contributors'' to create posts, videos and reviews; members must produce at least one piece of content per month, tag @XREAL_Global / #XREALVisionaries, and perks include product testing before launch, event invitations, exposure support and brand swag. The page names only nine current Visionaries (Katsuya, Kola, ketley2aug, eminus, justinseans, Getting Things Dun, Sensasian, JoyReignVR, UGEplex) — a deliberately small named cohort, supporting low creator saturation.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.xreal.com/us/visionaries', 'official_site', 'affiliate', 'Under ''Potential Collaboration'' the page states Visionaries ''may be invited to participate in our affiliate program, offering the opportunity to earn a commission on sales generated through your direct recommendations.'' No commission rate is published anywhere fetched, so commission_rate is null and commission_cap is unknown. Joining is by application form on the page with manual review, approval and an NDA-backed agreement.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.xreal.com/us/visionaries', 'official_site', 'contact', 'The page closes: ''To learn more about the program, including limits and availability, please email us at info@xreal.com'' — a published program contact email on the official creator page.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.crunchbase.com/organization/nreal-ai', 'listing', 'general', 'Crunchbase lists Xreal (legal name XREAL, Inc., formerly Nreal) as founded in 2017 and based in Beijing, China, a developer of lightweight ready-to-wear mixed reality glasses; TechCrunch (May 2026) covers XREAL as Google''s smart-glasses / Android XR partner for Project Aura.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 29, 18, 4, 11, 7, 5, '{"compensation": "Affiliate commission exists only as a possible invitation for Visionaries and no rate is published anywhere fetched, so this stays very low per the rubric.", "contact_access": "A published program email (info@xreal.com) plus a full application form on the official page.", "credibility": "Founded 2017, a leading global consumer AR-glasses provider and Google''s Android XR partner, with mainstream tech-press coverage.", "niche_fit": "Consumer AR glasses are peak technology UGC \u2014 unboxings, gaming/movie screen demos and XR reviews are the program''s exact content ask.", "opportunity_availability": "Applications are open now, but entry is manual-review and agreement/NDA based, and the program is described as voluntary.", "ugc_evidence": "A named, structured creator/ambassador program with a public roster, monthly content duties, product-testing and content-amplification perks \u2014 the strongest UGC evidence in this group."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Brooklyn Bedding', 'https://brooklynbedding.com', 'Vertically integrated US mattress and bedding manufacturer founded by brothers John and Rob Merwin in Phoenix, Arizona in 1995, which pioneered bed-in-a-box in 2008, makes its mattresses in its own Arizona factories at factory-direct prices, and since 2021 has sat within 3Z Brands alongside Helix Sleep.', 'United States', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'home'), true);
  insert into public.brand_contacts (brand_id, contact_type, email, contact_url, source_url, verification_status, last_verified_at) values (bid, 'creator_application', null, 'https://brooklynbedding.com/pages/ambassador-program', 'https://brooklynbedding.com/pages/ambassador-program', 'verified', now());
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Impact', 5, 'Commission cap: UNCAPPED — stated in the program terms (see evidence). Creator saturation: unknown (see evidence). Rate as reported by https://brooklynbedding.com/pages/ambassador-program.', 'https://brooklynbedding.com/pages/ambassador-program', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Brooklyn Bedding Ambassador Program', 'https://brooklynbedding.com/pages/ambassador-program', 'https://brooklynbedding.com/pages/ambassador-program', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://brooklynbedding.com/pages/ambassador-program', 'official_site', 'affiliate', 'Brooklyn Bedding''s official Ambassador Program page states verbatim: ''Earn a 5% commission on every Brooklyn Bedding Mattress sale made through your referral link'', ''A unique URL will be provided for you, via Impact'', and under the heading ''Uncapped Earnings'': ''The more you share your link the more you earn! Enjoy uncapped commissions when people shop your link.'' Sign-up is via Impact from the page.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://brooklynbedding.com/pages/ambassador-program', 'official_site', 'ugc_collab', 'The same page frames the programme for social sharing — step 3 is ''Share your referral link with friends, family, or social media followers'' — an ambassador model aimed at creators and advocates rather than only media publishers.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://brooklynbedding.com/pages/our-story', 'official_site', 'general', 'The brand''s own story page confirms it has been family-owned since 1995, launched bed-in-a-box in 2008, and designs and ships mattresses from its own state-of-the-art factory in Phoenix, Arizona.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 26, 14, 11, 8, 9, 5, '{"compensation": "A published 5% on mattress sales with commissions explicitly stated as uncapped on the official page; the percentage itself is modest but order values are high.", "contact_access": "A dedicated official programme page with a direct Impact sign-up route, but no published partnerships email.", "credibility": "Operating since 1995, a bed-in-a-box pioneer with its own US factories, now part of 3Z Brands with Helix Sleep.", "niche_fit": "Mattresses and bedding made in-house \u2014 a core home/sleep UGC category with big-ticket orders that make even a 5% rate meaningful per sale.", "opportunity_availability": "Open sign-up today from the official page \u2014 join on Impact, receive a personalised link once approved.", "ugc_evidence": "A named Ambassador Program on the brand''s own site, explicitly built around sharing referral links with social media followers."}'::jsonb);
